SELECT jsonb_pretty(jsonb_build_object(
 'ledger_count', (SELECT count(*) FROM supabase_migrations.schema_migrations),
 'versions_already_recorded', (SELECT coalesce(jsonb_agg(version),'[]') FROM supabase_migrations.schema_migrations WHERE version IN ('20251002210020','20251207160232','20260324051459','20260324154955')),
 'predecessors_recorded', (SELECT coalesce(jsonb_agg(version ORDER BY version),'[]') FROM supabase_migrations.schema_migrations WHERE version IN ('20251003200318','20260324180043')),
 'admin_settings', jsonb_build_object('table', to_regclass('public.admin_settings') IS NOT NULL, 'rls', (SELECT relrowsecurity FROM pg_class WHERE oid='public.admin_settings'::regclass), 'admin_notification_phone_present', EXISTS(SELECT 1 FROM public.admin_settings WHERE key='admin_notification_phone'), 'admin_notification_phone_length', (SELECT length(value) FROM public.admin_settings WHERE key='admin_notification_phone'), 'policies', (SELECT jsonb_agg(policyname ORDER BY policyname) FROM pg_policies WHERE schemaname='public' AND tablename='admin_settings')),
 'hero_carousel_images', jsonb_build_object('table', to_regclass('public.hero_carousel_images') IS NOT NULL, 'rls', (SELECT relrowsecurity FROM pg_class WHERE oid='public.hero_carousel_images'::regclass), 'trigger_hero_carousel_updated_at', EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.hero_carousel_images'::regclass AND tgname='hero_carousel_updated_at' AND NOT tgisinternal), 'row_count', (SELECT count(*) FROM public.hero_carousel_images), 'rows', (SELECT jsonb_agg(jsonb_build_object('id',id,'title',title,'display_order',display_order,'is_active',is_active,'image_url_sha256',encode(sha256(convert_to(image_url,'UTF8')),'hex')) ORDER BY display_order, id) FROM public.hero_carousel_images), 'pexels_seed_urls_present', EXISTS(SELECT 1 FROM public.hero_carousel_images WHERE image_url LIKE '%pexels%')),
 'realtime_publication_supabase_realtime', (SELECT coalesce(jsonb_agg(schemaname||'.'||tablename ORDER BY tablename),'[]') FROM pg_publication_tables WHERE pubname='supabase_realtime')
)) AS evidence;
